// EP2C5F256C8 scan2 core: scan_core (fpga/scan-ep2c5/scan_core.v, used
// unchanged, so the sweep-11 T0..T3 map and behaviour stay bit for bit)
// plus the g1x block (g1x.v) at addresses scan_core leaves unmapped.
// Hand-written; the port wrapper scan2.v is generated by
// tools/pinfind/mk_scan2.py. Map: docs/research/ep2c5-scan2.md.
//
// Outputs: d_out / d_oe exactly as scan_core (d_oe = ~ncs & ~nrd); g1x
// only replaces the data word at its own addresses.
module scan2_core #(
    parameter [15:0] WIN_LOG2   = 16'd22,  // scan_core window (2^22 H16 ticks)
    parameter [7:0]  G_WIN_LOG2 = 8'd28    // g1x window (2^28 H16 ticks, 5.59 s)
) (
    input  wire [141:0] raw,
    input  wire [7:0]   clk,
    input  wire [32:0]  dc,
    input  wire         c4,
    input  wire [7:0]   addr,
    input  wire         ncs,
    input  wire         nrd,
    output wire [15:0]  d_out,
    output wire         d_oe
);
    wire [15:0] d_s, d_g;
    wire g_hit;
    scan_core #(.WIN_LOG2(WIN_LOG2)) sc (
        .raw(raw), .clk(clk), .dc(dc), .addr(addr), .ncs(ncs), .nrd(nrd),
        .d_out(d_s), .d_oe(d_oe));
    g1x #(.WIN_LOG2(G_WIN_LOG2)) gx (
        .h16(clk[5]), .dc(dc), .c4(c4), .addr(addr), .ncs(ncs), .nrd(nrd),
        .hit(g_hit), .d_out(d_g));
    assign d_out = g_hit ? d_g : d_s;
endmodule
